import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 960;
const CX = W / 2;

const COLORS = {
  a: { fill: '#e3f2fd', stroke: '#1976d2' },
  b: { fill: '#fff3e0', stroke: '#f57c00' },
  c: { fill: '#e8f5e9', stroke: '#4caf50' },
  accum: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  tile: { fill: '#e0f2f1', stroke: '#00897b' },
  scalar: { fill: '#fff8e1', stroke: '#f9a825' },
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 72;
const MAT_W = 160;
const MAT_H = 104;
const TILE_W = 112;
const TILE_H = 84;
const VEC_W = 144;
const VEC_H = 38;
const COL_VEC_W = 38;
const COL_VEC_H = 144;
const STEP_GAP = 150;
const BOX_TO_ROW = 110;
const ROW_GAP = 130;
const SHAPE_GAP = 56;
const SIDE_OFF = 220;

interface MatmulStep extends StepInfo {}
type MatmulVariant = 'naive' | 'blocked';

function lbl(
  g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDownBetween(
  g: Gsel, x: number, yTop: number, targetTop: number, color = '#94a3b8', margin = 10
): void {
  if (targetTop - margin > yTop) {
    drawArrow(g as Sel, x, yTop, x, targetTop - margin, { color });
  }
}

function arrowHBetween(
  g: Gsel, xFrom: number, xTo: number, y: number, color = '#94a3b8', margin = 10
): void {
  const dir = xTo >= xFrom ? 1 : -1;
  drawArrow(g as Sel, xFrom + dir * margin, y, xTo - dir * margin, y, { color });
}

function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = 880
): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 26).attr('cy', y + BOX_H / 2)
    .attr('r', 15).attr('fill', stroke);
  lbl(g, cx - w / 2 + 26, y + BOX_H / 2 + 1, String(sn), { size: 13, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 - 6, title, { size: 14, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 + 12, formula, { size: 10, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.8 + 36, 240);
  const h = 32;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy + 1, text, { size: 10, color, font: 'monospace' });
}

function matrixBlock(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string, w = MAT_W, h = MAT_H,
  dimTop?: string, dimLeft?: string
): void {
  const top = dimTop ?? (sub.includes(',') ? sub.split(',')[1].trim().replace(/\]/, '') : '');
  const left = dimLeft ?? (sub.includes(',') ? sub.split(',')[0].trim().replace(/\[/, '') : '');
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke,
    cols: 8, rows: 6, dimTop: top, dimLeft: left,
  });
}

function tileBlock(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string
): void {
  drawMatrixBlock(g as Sel, cx - TILE_W / 2, cy - TILE_H / 2, {
    width: TILE_W, height: TILE_H, label, sublabel: sub, fill, stroke,
    cols: 4, rows: 4,
  });
}

function vecBlock(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string, vertical = false
): void {
  if (vertical) {
    drawMatrixBlock(g as Sel, cx - COL_VEC_W / 2, cy - COL_VEC_H / 2, {
      width: COL_VEC_W, height: COL_VEC_H, label, sublabel: sub, fill, stroke,
      cols: 1, rows: 8,
    });
  } else {
    drawMatrixBlock(g as Sel, cx - VEC_W / 2, cy - VEC_H / 2, {
      width: VEC_W, height: VEC_H, label, sublabel: sub, fill, stroke,
      cols: 8, rows: 1,
    });
  }
}

function scalarBlock(g: Gsel, cx: number, cy: number, label: string, sub = ''): void {
  drawMatrixBlock(g as Sel, cx - 32, cy - 32, {
    width: 64, height: 64, label, sublabel: sub, fill: COLORS.scalar.fill, stroke: COLORS.scalar.stroke,
    cols: 1, rows: 1,
  });
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 16)
    .attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 13, weight: '700', color });
}

function indexLabel(g: Gsel, x: number, y: number, text: string, color: string, anchor: 'start' | 'middle' | 'end' = 'middle'): void {
  lbl(g, x, y, text, { size: 11, weight: '700', color, anchor });
}

function paramSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 160;
  const h = 36;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => {
    lbl(g, cx - w / 2 + segW * (i + 0.5), y + h / 2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' });
  });
  return y + h;
}

function makeStep(
  id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]
): MatmulStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

function drawHighlightRow(g: Gsel, cx: number, cy: number, w: number, h: number, row: number, rows: number, color: string): void {
  const cellH = (h - 2) / rows;
  const y = cy - h / 2 + 1 + row * cellH;
  g.append('rect').attr('x', cx - w / 2 + 1).attr('y', y).attr('width', w - 2).attr('height', cellH - 1)
    .attr('fill', color).attr('opacity', 0.25).attr('stroke', color).attr('stroke-width', 1);
}

function drawHighlightCol(g: Gsel, cx: number, cy: number, w: number, h: number, col: number, cols: number, color: string): void {
  const cellW = (w - 2) / cols;
  const x = cx - w / 2 + 1 + col * cellW;
  g.append('rect').attr('x', x).attr('y', cy - h / 2 + 1).attr('width', cellW - 1).attr('height', h - 2)
    .attr('fill', color).attr('opacity', 0.25).attr('stroke', color).attr('stroke-width', 1);
}

// ═══════════════════════════════════════════════════════════════════════════════
// Naive renderer
// ═══════════════════════════════════════════════════════════════════════════════

function renderNaive(g: Gsel, yStart: number, m: number, k: number, n: number): { steps: MatmulStep[]; y: number } {
  const steps: MatmulStep[] = [];
  let stepId = 0;
  let y = yStart;

  // ── Step 1: Input matrices ─────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input Matrices',
      `A [${m}, ${k}], B [${k}, ${n}]`,
      COLORS.a.fill, COLORS.a.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    matrixBlock(gs, CX - SIDE_OFF, rowY, 'A', `[${m}, ${k}]`, COLORS.a.fill, COLORS.a.stroke, MAT_W, MAT_H, String(k), String(m));
    matrixBlock(gs, CX + SIDE_OFF, rowY, 'B', `[${k}, ${n}]`, COLORS.b.fill, COLORS.b.stroke, MAT_W, MAT_H, String(n), String(k));

    shapeEq(gs, CX, rowY + MAT_H / 2 + 28,
      `A [${m}, ${k}] @ B [${k}, ${n}] = C [${m}, ${n}]`, COLORS.c.stroke);

    steps.push(makeStep(stepId, 'Input', 'Input Matrices',
      `A [${m}, ${k}], B [${k}, ${n}]`,
      'Matrix multiplication takes two matrices A and B and produces C.',
      'step-input', COLORS.a.stroke, COLORS.a.fill,
      [`A = input matrix  # [${m}, ${k}]`,
       `B = input matrix  # [${k}, ${n}]`]));
    y = rowY + MAT_H / 2 + 28 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 2: Select row i and column j ──────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-select', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Select Output Position',
      `for i in [0, ${m}), for j in [0, ${n})`,
      COLORS.c.fill, COLORS.c.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    const aCx = CX - SIDE_OFF;
    const bCx = CX + SIDE_OFF;
    const hiRow = 1;
    const hiCol = 2;
    matrixBlock(gs, aCx, rowY, 'A', `[${m}, ${k}]`, COLORS.a.fill, COLORS.a.stroke, MAT_W, MAT_H, String(k), String(m));
    matrixBlock(gs, bCx, rowY, 'B', `[${k}, ${n}]`, COLORS.b.fill, COLORS.b.stroke, MAT_W, MAT_H, String(n), String(k));
    drawHighlightRow(gs, aCx, rowY, MAT_W, MAT_H, hiRow, 6, COLORS.a.stroke);
    drawHighlightCol(gs, bCx, rowY, MAT_W, MAT_H, hiCol, 8, COLORS.b.stroke);

    indexLabel(gs, aCx - MAT_W / 2 - 10, rowY - MAT_H / 2 + (hiRow + 0.5) * (MAT_H / 6), 'i', COLORS.a.stroke, 'end');
    indexLabel(gs, bCx - MAT_W / 2 + (hiCol + 0.5) * (MAT_W / 8), rowY - MAT_H / 2 - 30, 'j', COLORS.b.stroke, 'middle');

    const scalarCy = rowY + ROW_GAP;
    scalarBlock(gs, CX, scalarCy, 'C[i,j]');
    arrowDownBetween(gs, aCx, rowY + MAT_H / 2, scalarCy - 32, COLORS.a.stroke);
    arrowDownBetween(gs, bCx, rowY + MAT_H / 2, scalarCy - 32, COLORS.b.stroke);

    shapeEq(gs, CX, scalarCy + 40,
      `C[i, j] = A[i, :] · B[:, j]`, COLORS.c.stroke);

    steps.push(makeStep(stepId, 'Select', 'Select Output Position',
      `for i in [0, ${m}), for j in [0, ${n})`,
      'The naive algorithm loops over every output position (i, j).',
      'step-select', COLORS.c.stroke, COLORS.c.fill,
      [`for i in range(${m}):`,
       `    for j in range(${n}):`,
       `        C[i, j] = 0`]));
    y = scalarCy + 40 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 3: Inner dot product ──────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-dot', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Inner Loop: Dot Product',
      `C[i, j] += A[i, p] * B[p, j]  for p in [0, ${k})`,
      COLORS.c.fill, COLORS.c.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    const aCx = CX - SIDE_OFF;
    const bCx = CX + SIDE_OFF;
    vecBlock(gs, aCx, rowY, 'A[i,:]', `[${k}]`, COLORS.a.fill, COLORS.a.stroke, false);
    vecBlock(gs, bCx, rowY, 'B[:,j]', `[${k}]`, COLORS.b.fill, COLORS.b.stroke, true);
    opCircle(gs, CX, rowY, '·', COLORS.c.stroke);

    const scalarCy = rowY + ROW_GAP;
    scalarBlock(gs, CX, scalarCy, 'C[i,j]');

    arrowHBetween(gs, aCx + VEC_W / 2, CX - 16, rowY, COLORS.a.stroke);
    drawArrow(g as Sel, bCx - COL_VEC_W / 2, rowY, CX + 16, rowY, { color: COLORS.b.stroke });
    arrowDownBetween(gs, CX, rowY + 16, scalarCy - 32, COLORS.c.stroke);

    lbl(gs, CX + 90, rowY + ROW_GAP / 2, `for p = 0 … ${k - 1}`, {
      size: 10, color: COLORS.muted, anchor: 'start'
    });

    shapeEq(gs, CX, scalarCy + 40,
      `C[i, j] = Σ_{p=0}^{${k - 1}} A[i, p] · B[p, j]`, COLORS.c.stroke);

    steps.push(makeStep(stepId, 'Dot', 'Inner Loop: Dot Product',
      `C[i, j] += A[i, p] * B[p, j]`,
      'For each output position, multiply matching elements and sum them up.',
      'step-dot', COLORS.c.stroke, COLORS.c.fill,
      [`for p in range(${k}):`,
       `    C[i, j] += A[i, p] * B[p, j]`]));
    y = scalarCy + 40 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 4: Output C ───────────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Output Matrix',
      `C = A @ B  →  [${m}, ${n}]`,
      COLORS.c.fill, COLORS.c.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    const hiRow = 1;
    const hiCol = 2;
    matrixBlock(gs, CX, rowY, 'C', `[${m}, ${n}]`, COLORS.c.fill, COLORS.c.stroke, 200, MAT_H, String(n), String(m));
    drawHighlightRow(gs, CX, rowY, 200, MAT_H, hiRow, 6, COLORS.a.stroke);
    drawHighlightCol(gs, CX, rowY, 200, MAT_H, hiCol, 8, COLORS.b.stroke);

    indexLabel(gs, CX - 100 - 10, rowY - MAT_H / 2 + (hiRow + 0.5) * (MAT_H / 6), 'i', COLORS.a.stroke, 'end');
    indexLabel(gs, CX - 100 + (hiCol + 0.5) * (200 / 8), rowY - MAT_H / 2 - 30, 'j', COLORS.b.stroke, 'middle');

    lbl(gs, CX, rowY - MAT_H / 2 - 44, 'Result Matrix', { size: 13, color: COLORS.c.stroke, weight: '700' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 28,
      `C = A @ B  →  [${m}, ${n}]`, COLORS.c.stroke);

    steps.push(makeStep(stepId, 'Output', 'Output Matrix',
      `C [${m}, ${n}]`,
      'After looping over all i, j, and p, the result matrix C is complete.',
      'step-output', COLORS.c.stroke, COLORS.c.fill,
      [`# Result`,
       `C = A @ B  # [${m}, ${n}]`]));
    y = rowY + MAT_H / 2 + 28 + SHAPE_GAP;
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Blocked renderer
// ═══════════════════════════════════════════════════════════════════════════════

function renderBlocked(g: Gsel, yStart: number, m: number, k: number, n: number): { steps: MatmulStep[]; y: number } {
  const steps: MatmulStep[] = [];
  let stepId = 0;
  let y = yStart;
  const b = Math.max(1, Math.min(32, Math.min(m, k, n)));
  const numTilesK = Math.ceil(k / b);

  // ── Step 1: Input matrices with tile grid ──────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input Matrices',
      `A [${m}, ${k}], B [${k}, ${n}]`,
      COLORS.a.fill, COLORS.a.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    matrixBlock(gs, CX - SIDE_OFF, rowY, 'A', `[${m}, ${k}]`, COLORS.a.fill, COLORS.a.stroke, MAT_W, MAT_H, String(k), String(m));
    matrixBlock(gs, CX + SIDE_OFF, rowY, 'B', `[${k}, ${n}]`, COLORS.b.fill, COLORS.b.stroke, MAT_W, MAT_H, String(n), String(k));
    drawTileGrid(gs, CX - SIDE_OFF, rowY, MAT_W, MAT_H, b, k);
    drawTileGrid(gs, CX + SIDE_OFF, rowY, MAT_W, MAT_H, b, k, true);

    shapeEq(gs, CX, rowY + MAT_H / 2 + 28,
      `A [${m}, ${k}] @ B [${k}, ${n}] = C [${m}, ${n}]  (tile size b=${b})`, COLORS.tile.stroke);

    steps.push(makeStep(stepId, 'Input', 'Input Matrices',
      `A [${m}, ${k}], B [${k}, ${n}]`,
      'Blocked matmul partitions the input matrices into small cache-friendly tiles.',
      'step-input', COLORS.a.stroke, COLORS.a.fill,
      [`A = input matrix  # [${m}, ${k}]`,
       `B = input matrix  # [${k}, ${n}]`,
       `b = tile size     # ${b}`]));
    y = rowY + MAT_H / 2 + 28 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 2: Highlight tiles ────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-tile', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Select Tiles',
      `A_ik = A[i0:i0+b, p0:p0+b]   B_kj = B[p0:p0+b, j0:j0+b]`,
      COLORS.tile.fill, COLORS.tile.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    tileBlock(gs, CX - SIDE_OFF, rowY, 'A_ik', `[${b}, ${b}]`, COLORS.a.fill, COLORS.a.stroke);
    tileBlock(gs, CX + SIDE_OFF, rowY, 'B_kj', `[${b}, ${b}]`, COLORS.b.fill, COLORS.b.stroke);

    indexLabel(gs, CX - SIDE_OFF, rowY - TILE_H / 2 - 20, 'row block i', COLORS.a.stroke, 'middle');
    indexLabel(gs, CX + SIDE_OFF, rowY - TILE_H / 2 - 20, 'col block j', COLORS.b.stroke, 'middle');
    indexLabel(gs, CX - SIDE_OFF + TILE_W / 2 + 18, rowY, 'K block k', COLORS.tile.stroke, 'start');
    indexLabel(gs, CX + SIDE_OFF - TILE_W / 2 - 18, rowY, 'K block k', COLORS.tile.stroke, 'end');

    shapeEq(gs, CX, rowY + TILE_H / 2 + 28,
      `A_ik [${b}, ${b}] @ B_kj [${b}, ${b}]  →  partial_ij [${b}, ${b}]`, COLORS.tile.stroke);

    steps.push(makeStep(stepId, 'Tile', 'Select Tiles',
      `A_ik [${b}, ${b}], B_kj [${b}, ${b}]`,
      'For each output tile, load a small tile of A and a small tile of B into cache.',
      'step-tile', COLORS.tile.stroke, COLORS.tile.fill,
      [`for i0 in range(0, ${m}, ${b}):`,
       `    for j0 in range(0, ${n}, ${b}):`,
       `        for p0 in range(0, ${k}, ${b}):`,
       `            A_ik = A[i0:i0+b, p0:p0+b]`]));
    y = rowY + TILE_H / 2 + 28 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 3: Partial product ────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-partial', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Compute Partial Product',
      `partial_ij += A_ik @ B_kj`,
      COLORS.c.fill, COLORS.c.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    tileBlock(gs, CX - SIDE_OFF, rowY, 'A_ik', `[${b}, ${b}]`, COLORS.a.fill, COLORS.a.stroke);
    tileBlock(gs, CX + SIDE_OFF, rowY, 'B_kj', `[${b}, ${b}]`, COLORS.b.fill, COLORS.b.stroke);
    opCircle(gs, CX, rowY, '@', COLORS.c.stroke);
    tileBlock(gs, CX, rowY + ROW_GAP, 'partial_ij', `[${b}, ${b}]`, COLORS.c.fill, COLORS.c.stroke);

    arrowHBetween(gs, CX - SIDE_OFF + TILE_W / 2, CX - 16, rowY, COLORS.a.stroke);
    drawArrow(g as Sel, CX + SIDE_OFF - TILE_W / 2, rowY, CX + 16, rowY, { color: COLORS.b.stroke });
    arrowDownBetween(gs, CX, rowY + 16, rowY + ROW_GAP - TILE_H / 2, COLORS.c.stroke);

    shapeEq(gs, CX, rowY + ROW_GAP + TILE_H / 2 + 28,
      `partial_ij += A_ik @ B_kj  →  [${b}, ${b}]`, COLORS.c.stroke);

    steps.push(makeStep(stepId, 'Partial', 'Compute Partial Product',
      `partial_ij += A_ik @ B_kj`,
      'Each tile pair produces a partial product tile that contributes to one output tile.',
      'step-partial', COLORS.c.stroke, COLORS.c.fill,
      [`A_ik = A[i0:i0+b, p0:p0+b]  # [${b}, ${b}]`,
       `B_kj = B[p0:p0+b, j0:j0+b]  # [${b}, ${b}]`,
       `partial_ij += A_ik @ B_kj   # [${b}, ${b}]`]));
    y = rowY + ROW_GAP + TILE_H / 2 + 28 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 4: Accumulate over K tiles ────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-accum', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Accumulate Over K Tiles',
      `C_ij = Σ_{k=0}^{${numTilesK - 1}} A_ik @ B_kj`,
      COLORS.accum.fill, COLORS.accum.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    const accumCy = rowY + ROW_GAP;
    tileBlock(gs, CX, accumCy, 'C_ij', `[${b}, ${b}]`, COLORS.accum.fill, COLORS.accum.stroke);

    const maxShownPartials = 4;
    const showPartials = Math.min(numTilesK, maxShownPartials);
    const partialGap = TILE_W + 40;
    const partialSpan = (showPartials - 1) * partialGap;
    const partialStart = CX - partialSpan / 2;
    const centers: number[] = [];
    for (let i = 0; i < showPartials; i++) centers.push(partialStart + i * partialGap);
    const partialY = rowY;
    centers.forEach((px, idx) => {
      tileBlock(gs, px, partialY, `partial_${idx}`, `[${b}, ${b}]`, COLORS.c.fill, COLORS.c.stroke);
      if (idx < centers.length - 1) {
        opCircle(gs, px + partialGap / 2, partialY, '+', COLORS.c.stroke);
      }
      arrowDownBetween(gs, px, partialY + TILE_H / 2, accumCy - TILE_H / 2, COLORS.c.stroke);
    });

    const sigmaX = centers[centers.length - 1] + TILE_W / 2 + 20;
    lbl(gs, sigmaX, partialY + 4, `Σ over k = 0 … ${numTilesK - 1}`, {
      size: 10, color: COLORS.accum.stroke, weight: '600', anchor: 'start'
    });

    shapeEq(gs, CX, accumCy + TILE_H / 2 + 28,
      `C_ij = Σ_k A_ik @ B_kj  →  [${b}, ${b}]`, COLORS.accum.stroke);

    steps.push(makeStep(stepId, 'Accum', 'Accumulate Over K Tiles',
      `C_ij = Σ_k A_ik @ B_kj`,
      'The output tile is the sum of partial products from all K tiles.',
      'step-accum', COLORS.accum.stroke, COLORS.accum.fill,
      [`for p0 in range(0, ${k}, ${b}):`,
       `    A_ik = A[i0:i0+b, p0:p0+b]`,
       `    B_kj = B[p0:p0+b, j0:j0+b]`,
       `    C_ij += A_ik @ B_kj`]));
    y = accumCy + TILE_H / 2 + 28 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 5: Assemble output ────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Assemble Output Matrix',
      `C = assemble(C_ij)  →  [${m}, ${n}]`,
      COLORS.c.fill, COLORS.c.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    const gridCols = 3;
    const gridRows = 2;
    const tileGap = 12;
    const gridW = gridCols * TILE_W + (gridCols - 1) * tileGap;
    const gridH = gridRows * TILE_H + (gridRows - 1) * tileGap;
    const startX = CX - gridW / 2 + TILE_W / 2;
    const gridYOffset = 50;
    const startY = rowY + gridYOffset - gridH / 2 + TILE_H / 2;
    for (let r = 0; r < gridRows; r++) {
      for (let c = 0; c < gridCols; c++) {
        tileBlock(gs, startX + c * (TILE_W + tileGap), startY + r * (TILE_H + tileGap),
          `C_${r}${c}`, `[${b}, ${b}]`, COLORS.c.fill, COLORS.c.stroke);
      }
    }

    lbl(gs, CX, rowY + gridYOffset - gridH / 2 - 24, 'Assembled Result', { size: 13, color: COLORS.c.stroke, weight: '700' });

    const outputGap = 210;
    arrowDownBetween(gs, CX, startY + gridH / 2, rowY + outputGap - MAT_H / 2, COLORS.c.stroke, 18);
    matrixBlock(gs, CX, rowY + outputGap, 'C', `[${m}, ${n}]`, COLORS.c.fill, COLORS.c.stroke, 200, MAT_H, String(n), String(m));

    shapeEq(gs, CX, rowY + outputGap + MAT_H / 2 + 28,
      `C = assemble(C_ij)  →  [${m}, ${n}]`, COLORS.c.stroke);

    steps.push(makeStep(stepId, 'Output', 'Assemble Output Matrix',
      `C [${m}, ${n}]`,
      'All output tiles are placed into their final positions to form C.',
      'step-output', COLORS.c.stroke, COLORS.c.fill,
      [`# Assemble full output`,
       `C[i0:i0+b, j0:j0+b] = C_ij`,
       `# C shape: [${m}, ${n}]`]));
    y = rowY + outputGap + MAT_H / 2 + 28 + SHAPE_GAP;
  }

  return { steps, y };
}

function drawTileGrid(
  g: Gsel, cx: number, cy: number, w: number, h: number,
  b: number, dim: number, vertical: boolean = false
): void {
  const group = g.append('g');
  const nTiles = Math.min(4, Math.ceil(dim / b));
  if (vertical) {
    for (let i = 1; i < nTiles; i++) {
      const y = cy - h / 2 + i * (h / nTiles);
      group.append('line').attr('x1', cx - w / 2 + 1).attr('y1', y).attr('x2', cx + w / 2 - 1).attr('y2', y)
        .attr('stroke', COLORS.tile.stroke).attr('stroke-width', 1).attr('stroke-dasharray', '3,3').attr('opacity', 0.5);
    }
  } else {
    for (let i = 1; i < nTiles; i++) {
      const x = cx - w / 2 + i * (w / nTiles);
      group.append('line').attr('x1', x).attr('y1', cy - h / 2 + 1).attr('x2', x).attr('y2', cy + h / 2 - 1)
        .attr('stroke', COLORS.tile.stroke).attr('stroke-width', 1).attr('stroke-dasharray', '3,3').attr('opacity', 0.5);
    }
  }
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main renderer
// ═══════════════════════════════════════════════════════════════════════════════

export function renderMatmulDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const m = Number(params.m) || 128;
  const k = Number(params.k) || 256;
  const n = Number(params.n) || 512;
  const variant = String(params.variant || 'naive') as MatmulVariant;

  const stepsMeta: MatmulStep[] = [];
  let y = 10;

  // Title
  lbl(g, CX, y + 14, 'Matrix Multiply', { size: 18, weight: '700', color: 'var(--text)' });
  y += 36;
  lbl(g, CX, y + 8,
    `${variant === 'blocked' ? 'Blocked / Tiled' : 'Naive'} matrix multiplication — explicit matrices and computation`,
    { size: 10, color: 'var(--text-muted)' });
  y += 30;

  y = paramSummary(g, CX, y, [
    `m: ${m}`, `k: ${k}`, `n: ${n}`, `variant: ${variant.toUpperCase()}`,
  ]);
  y += 32;

  const { steps, y: finalY } = variant === 'blocked'
    ? renderBlocked(g, y, m, k, n)
    : renderNaive(g, y, m, k, n);
  stepsMeta.push(...steps);
  y = finalY;

  // ── Footer ─────────────────────────────────────────────────────────────────
  y += 32;
  const insightText = variant === 'blocked'
    ? 'Blocked matmul improves cache reuse by keeping small tiles in fast cache while computing partial products. Modern GEMM libraries add vectorization, register tiling, and parallelization on top of this idea.'
    : 'Naive matmul is easy to understand but has poor cache behavior: the inner loop strides through columns of B, causing many cache misses. It is mainly used for teaching and small matrices.';

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, insightText, 'insight');
  y += 24;

  const perfText = `Total FLOPs ≈ 2·m·k·n = ${(2 * m * k * n).toLocaleString()}. Memory traffic is ${((m * k + k * n + m * n) * 4).toLocaleString()} bytes for fp32 inputs+output. Blocked variants reduce cache misses and can be orders of magnitude faster for large matrices.`;
  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, perfText, 'perf');
  y += 24;

  drawComponentLink(g as Sel, CX - (W - 160) / 2, y, (W - 160) / 2 - 8, 56, 'attention', 'Attention');
  drawComponentLink(g as Sel, CX + 8, y, (W - 160) / 2 - 8, 56, 'mlp', 'MLP');
  y += 72;

  const codeTitle = `Matrix Multiply — ${variant === 'blocked' ? 'Blocked' : 'Naive'} (Python)`;
  const codeLines = variant === 'blocked'
    ? [`# Blocked matmul (tile size b)`,
       `def matmul_blocked(A, B, b=${Math.max(1, Math.min(32, Math.min(m, k, n)))}):`,
       `    m, k = A.shape; k2, n = B.shape`,
       `    C = torch.zeros(m, n)`,
       `    for i0 in range(0, m, b):`,
       `        for j0 in range(0, n, b):`,
       `            C_ij = torch.zeros(b, b)`,
       `            for p0 in range(0, k, b):`,
       `                A_ik = A[i0:i0+b, p0:p0+b]`,
       `                B_kj = B[p0:p0+b, j0:j0+b]`,
       `                C_ij += A_ik @ B_kj`,
       `            C[i0:i0+b, j0:j0+b] = C_ij`,
       `    return C`]
    : [`# Naive O(n^3) matmul`,
       `def matmul_naive(A, B):`,
       `    m, k = A.shape; k2, n = B.shape`,
       `    C = torch.zeros(m, n)`,
       `    for i in range(m):`,
       `        for j in range(n):`,
       `            for p in range(k):`,
       `                C[i, j] += A[i, p] * B[p, j]`,
       `    return C`];

  drawCodeAnnotation(g as Sel, CX - (W - 160) / 2, y, W - 160, codeTitle,
    [`${variant === 'blocked' ? 'Blocked' : 'Naive'} matmul — A[${m},${k}] @ B[${k},${n}] → C[${m},${n}]`], codeLines);

  return { width: W, height: y + 160, steps: stepsMeta };
}
